/**
 * @ohos/dsh-tool-python — `python_run`, backed by Pyodide in the app's WebView.
 *
 * HarmonyOS forbids fork/exec, so a `python` binary can never be spawned. The
 * interpreter is embedded instead: a hidden 1×1 WebView (`view/PythonHost.ets`)
 * loads Pyodide and the ArkTS side polls a directory. The dsh plugin and the
 * app never share a socket or a native handle, only two small JSON files:
 *
 *   <DSH_HOME>/python/req/req-<id>.json   plugin → app
 *   <DSH_HOME>/python/res/res-<id>.json   app → plugin
 *   <DSH_HOME>/python/status.json         readiness / last load error
 *
 * The file protocol is deliberately boring: either side can restart without a
 * handshake, and a request that never gets answered simply times out with the
 * runtime's last status attached. Output is capped because model context, not
 * disk, is the scarce resource.
 */

import { defineTool } from "@deepseek-ai/dsh-tools";
import { HarnessError } from "@deepseek-ai/dsh-llm";
import { randomUUID } from "node:crypto";
import { existsSync } from "node:fs";
import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { basename, join } from "node:path";

const name = "tool-python-ohos";
const inject = ["tools", "fs", "workingDirectory"];

const DEFAULT_TIMEOUT_MS = 90000;
const MAX_TIMEOUT_MS = 300000;
const POLL_MS = 150;
const MAX_CODE_CHARS = 200000;
const MAX_STDOUT_CHARS = 30000;
const MAX_STDERR_CHARS = 10000;
const MAX_FILES = 8;
const MAX_FILE_BYTES = 5 * 1024 * 1024;
const MAX_TOTAL_FILE_BYTES = 15 * 1024 * 1024;
const PYBOT_MARKER = "__PYBOT__";
const PYBOT_DEFAULT_TIMEOUT_MS = 120000;
const MAX_PYBOT_TEXT_CHARS = 20000;
const MAX_PYBOT_THREAD_CHARS = 200;

/** Typed Python-run failure with a stable, model-facing code. */
class PythonError extends HarnessError {
	constructor(message, code) {
		super(message);
		this.name = "PythonError";
		this.code = code;
	}
}

function pythonHome() {
	const home = process.env.DSH_HOME;
	if (typeof home !== "string" || home.length === 0) {
		throw new PythonError("DSH_HOME is not set; the Python bridge cannot find its request directory", "PYTHON_NO_HOME");
	}
	return join(home, "python");
}

function clip(text, limit) {
	const value = String(text ?? "");
	if (value.length <= limit) return value;
	return `${value.slice(0, limit)}\n…（输出超出上限，已截断 ${value.length - limit} 字符）`;
}

function sleep(ms) {
	return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Read the runtime's last status, tolerating absence/corruption. */
async function readStatus(home) {
	try {
		const text = await readFile(join(home, "status.json"), "utf8");
		const status = JSON.parse(text);
		if (status !== null && typeof status === "object") return status;
	} catch (_) {
		/* no status yet */
	}
	return undefined;
}

/** Human-readable suffix for a timeout: the load error matters more than the wait. */
function statusHint(status) {
	if (status === undefined) return "";
	if (status.ok === false && typeof status.error === "string" && status.error.length > 0) {
		return ` Python 运行时加载失败：${status.error}`;
	}
	if (typeof status.version === "string" && status.version.length > 0) {
		return ` Python 已就绪（${status.version.split(" ")[0]}）。`;
	}
	return "";
}

/**
 * Write one request and wait for its response file.
 * Exported for the host-side tests; the tool wrapper only validates arguments.
 */
/**
 * Read workspace files into base64 for the Pyodide in-memory FS.
 * The fence is the same one the Office tools use: resolve inside the session
 * workspace, refuse `..`/absolute escapes, cap each file and the total.
 */
async function readInputFiles(ctx, exec, paths) {
	if (!Array.isArray(paths) || paths.length === 0) return [];
	if (paths.length > MAX_FILES) {
		throw new PythonError(`too many files (${paths.length} > ${MAX_FILES})`, "PYTHON_TOO_LARGE");
	}
	const cwd = await ctx.workingDirectory.ensure(exec.agent, exec.signal);
	const root = await ctx.fs.resolve(cwd);
	const out = [];
	let total = 0;
	for (const input of paths) {
		const clean = String(input ?? "").trim();
		if (clean.length === 0) throw new PythonError("file path cannot be empty", "PYTHON_BAD_ARGS");
		const target = await ctx.fs.resolve(clean, { cwd, signal: exec.signal });
		if (!ctx.fs.contains(root, target)) {
			throw new PythonError(`file escapes the session workspace: ${clean}`, "PYTHON_SANDBOX_DENIED");
		}
		const info = await ctx.fs.stat(target, exec.signal);
		if (info === undefined || info.type !== "file") {
			throw new PythonError(`file not found: ${clean}`, "PYTHON_NOT_FOUND");
		}
		if (info.size !== undefined && info.size > MAX_FILE_BYTES) {
			throw new PythonError(`file is too large for the Python bridge (${info.size} > ${MAX_FILE_BYTES})`, "PYTHON_TOO_LARGE");
		}
		const bytes = await ctx.fs.readBytes(target, exec.signal, MAX_FILE_BYTES);
		total += bytes.length;
		if (total > MAX_TOTAL_FILE_BYTES) {
			throw new PythonError(`input files exceed the ${MAX_TOTAL_FILE_BYTES} byte bridge limit`, "PYTHON_TOO_LARGE");
		}
		out.push({
			name: basename(clean),
			data: Buffer.from(bytes).toString("base64")
		});
	}
	return out;
}

async function runPython(code, options = {}) {
	const timeoutMs = Math.max(1000, Math.min(MAX_TIMEOUT_MS, options.timeoutMs ?? DEFAULT_TIMEOUT_MS));
	const home = pythonHome();
	const reqDir = join(home, "req");
	const resDir = join(home, "res");
	await mkdir(reqDir, { recursive: true });
	await mkdir(resDir, { recursive: true });

	const id = randomUUID();
	const reqPath = join(reqDir, `req-${id}.json`);
	const resPath = join(resDir, `res-${id}.json`);
	const temp = `${reqPath}.tmp-${process.pid.toString(36)}-${Date.now().toString(36)}`;
	await writeFile(temp, JSON.stringify({
		id,
		code,
		timeoutMs,
		files: options.files ?? [],
		packages: options.packages ?? ["pandas"]
	}), "utf8");
	await rename(temp, reqPath);

	const started = Date.now();
	try {
		while (Date.now() - started < timeoutMs) {
			if (existsSync(resPath)) {
				const text = await readFile(resPath, "utf8");
				await unlink(resPath).catch(() => {});
				let parsed;
				try {
					parsed = JSON.parse(text);
				} catch (error) {
					throw new PythonError(`Python 返回了无法解析的结果：${error.message}`, "PYTHON_BAD_RESULT");
				}
				return {
					ok: parsed.ok === true,
					stdout: clip(parsed.stdout, MAX_STDOUT_CHARS),
					stderr: clip(parsed.stderr, MAX_STDERR_CHARS),
					value: typeof parsed.value === "string" ? clip(parsed.value, MAX_STDOUT_CHARS) : "",
					error: typeof parsed.error === "string" ? parsed.error : "",
					durationMs: Date.now() - started
				};
			}
			await sleep(POLL_MS);
		}
	} finally {
		await unlink(reqPath).catch(() => {});
	}

	const status = await readStatus(home);
	throw new PythonError(
		`Python 运行在 ${Math.round(timeoutMs / 1000)} 秒内没有返回结果。${statusHint(status)}` +
			"第一次运行需要加载解释器（几秒），之后会快很多；如果一直超时，去设置 → 诊断看 PythonRuntime 日志。",
		"PYTHON_TIMEOUT"
	);
}

/** Validate and normalize `python_run` arguments. */
function parseArgs(args) {
	const code = typeof args.code === "string" ? args.code : "";
	if (code.trim().length === 0) {
		throw new PythonError("code is required", "PYTHON_BAD_ARGS");
	}
	if (code.length > MAX_CODE_CHARS) {
		throw new PythonError(`code is too long (${code.length} > ${MAX_CODE_CHARS} characters)`, "PYTHON_TOO_LARGE");
	}
	const timeout = typeof args.timeout_ms === "number" && Number.isFinite(args.timeout_ms) && args.timeout_ms > 0
		? Math.floor(args.timeout_ms)
		: DEFAULT_TIMEOUT_MS;
	let packages = ["pandas"];
	if (args.packages !== undefined) {
		if (!Array.isArray(args.packages) || args.packages.some((entry) => typeof entry !== "string")) {
			throw new PythonError("packages must be an array of Pyodide package names", "PYTHON_BAD_ARGS");
		}
		packages = args.packages;
	}
	let files = [];
	if (args.files !== undefined) {
		if (!Array.isArray(args.files) || args.files.some((entry) => typeof entry !== "string")) {
			throw new PythonError("files must be an array of workspace paths", "PYTHON_BAD_ARGS");
		}
		files = args.files;
	}
	return { code, timeoutMs: Math.max(1000, Math.min(MAX_TIMEOUT_MS, timeout)), files, packages };
}

function renderResult(value) {
	const lines = [];
	if (value.value.length > 0) lines.push(value.value.trimEnd());
	if (value.stdout.length > 0) lines.push(value.stdout.trimEnd());
	if (value.stderr.length > 0) lines.push(`stderr:\n${value.stderr.trimEnd()}`);
	if (lines.length === 0) lines.push("（没有输出）");
	return lines.join("\n");
}

/** Encode a Python string literal without letting model text break the code. */
function b64(value) {
	return Buffer.from(String(value), "utf8").toString("base64");
}

/** Build the pybot turn code. Memory is per thread, cached in the worker. */
function buildPybotCode(text, thread, reset) {
	return [
		"import sys, json, base64, builtins",
		"sys.path.insert(0, '/pybot.zip')",
		"import pybot",
		`text = base64.b64decode('${b64(text)}').decode('utf-8')`,
		`thread = base64.b64decode('${b64(thread)}').decode('utf-8')`,
		"states = getattr(builtins, '_pybot_states', None)",
		"if not isinstance(states, dict):",
		"    states = {}",
		"    builtins._pybot_states = states",
		`if ${reset ? "True" : "False"} or thread not in states:`,
		"    states[thread] = (pybot.load_bot(), {})",
		"runtime, memory = states[thread]",
		"reply, module, seconds = pybot.answer(runtime, text, memory)",
		`print('${PYBOT_MARKER}' + json.dumps({'reply': reply, 'module': module, 'seconds': seconds}))`
	].join("\n");
}

/** Parse the one marker line pybot prints; tolerate module debug output. */
function parsePybotOutput(stdout) {
	const line = String(stdout ?? "").split("\n").find((entry) => entry.startsWith(PYBOT_MARKER));
	if (line === undefined) {
		throw new PythonError("pybot returned no reply marker", "PYBOT_BAD_RESULT");
	}
	let parsed;
	try {
		parsed = JSON.parse(line.slice(PYBOT_MARKER.length));
	} catch (error) {
		throw new PythonError(`pybot returned invalid JSON: ${error.message}`, "PYBOT_BAD_RESULT");
	}
	if (parsed === null || typeof parsed !== "object" || typeof parsed.reply !== "string") {
		throw new PythonError("pybot returned an invalid reply", "PYBOT_BAD_RESULT");
	}
	return {
		reply: parsed.reply,
		module: typeof parsed.module === "string" ? parsed.module : "",
		seconds: typeof parsed.seconds === "number" ? parsed.seconds : 0
	};
}

function parsePybotArgs(args) {
	const text = typeof args.text === "string" ? args.text : "";
	if (text.trim().length === 0) throw new PythonError("text is required", "PYBOT_BAD_ARGS");
	if (text.length > MAX_PYBOT_TEXT_CHARS) {
		throw new PythonError(`text is too long (${text.length} > ${MAX_PYBOT_TEXT_CHARS})`, "PYBOT_TOO_LARGE");
	}
	const thread = typeof args.thread === "string" && args.thread.trim().length > 0 ? args.thread.trim() : "default";
	if (thread.length > MAX_PYBOT_THREAD_CHARS) {
		throw new PythonError(`thread is too long (${thread.length} > ${MAX_PYBOT_THREAD_CHARS})`, "PYBOT_BAD_ARGS");
	}
	const timeoutMs = typeof args.timeout_ms === "number" && Number.isFinite(args.timeout_ms) && args.timeout_ms > 0
		? Math.min(MAX_TIMEOUT_MS, Math.max(1000, Math.floor(args.timeout_ms)))
		: PYBOT_DEFAULT_TIMEOUT_MS;
	return { text, thread, reset: args.reset === true, timeoutMs };
}

async function runPybot(text, options = {}) {
	const result = await runPython(buildPybotCode(text, options.thread ?? "default", options.reset === true), {
		timeoutMs: options.timeoutMs ?? PYBOT_DEFAULT_TIMEOUT_MS,
		packages: [],
		files: []
	});
	if (!result.ok) {
		throw new PythonError(`pybot 执行失败：${result.stderr || result.error}`, "PYBOT_FAILED");
	}
	const parsed = parsePybotOutput(result.stdout);
	return { ...parsed, durationMs: result.durationMs };
}

function apply(ctx) {
	const tool = defineTool({
		name: "python_run",
		description:
			"Run Python 3.13 (Pyodide) inside the app, no shell and no fork. " +
			"Use it for calculations, data wrangling, text processing and pure-Python scripts. " +
			"The runtime has an in-memory filesystem. Pass workspace files through the `files` argument; each is copied to " +
			"`/workspace/<basename>` inside Python (read-only input, max 5 MB/file and 15 MB total). It cannot write back to " +
			"the device: emit results as stdout or use the write/office tools for files. " +
			"Pyodide packages are preloaded per call by `packages` (default [\"pandas\"]; pass [] to avoid the ~300MB numpy/pandas cost). " +
			"`/pybot.zip` is bundled: add it to sys.path, import pybot, and call pybot.load_bot()/pybot.answer(); set packages=[] on this tool to skip numpy/pandas. " +
			"The first call can take several seconds while the interpreter warms up. " +
			"stdout, stderr and the expression value are returned; output is capped.",
		parameters: {
			code: {
				type: "string",
				required: true,
				description: "Python source to execute. Use print() for output; the last expression's value is also returned."
			},
			timeout_ms: {
				type: "number",
				description: `Wall-clock budget in milliseconds (default ${DEFAULT_TIMEOUT_MS}, max ${MAX_TIMEOUT_MS}).`
			},
			files: {
				type: "array",
				items: { type: "string" },
				description: "Workspace-relative files to copy into `/workspace/<basename>` before the run (max 8 files, 5 MB each, 15 MB total)."
			},
			packages: {
				type: "array",
				items: { type: "string" },
				description: "Pyodide packages to load before the run (default [\"pandas\"]; pass [] for pybot)."
			}
		},
		timeoutMs: MAX_TIMEOUT_MS + 5000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					ok: { type: "boolean", required: true },
					stdout: { type: "string", required: true },
					stderr: { type: "string", required: true },
					value: { type: "string", required: true },
					durationMs: { type: "number", required: true }
				}
			},
			render: (_args, value) => [{
				type: "text",
				text: `Python（${value.durationMs}ms）\n${renderResult(value)}`
			}]
		},
		presentCall: () => ({
			card: "generic",
			title: "Run Python",
			kind: "execute"
		}),
		isConcurrencySafe: () => false,
		async execute(args, exec) {
			const input = parseArgs(args);
			const files = await readInputFiles(ctx, exec, input.files);
			const result = await runPython(input.code, {
				timeoutMs: input.timeoutMs,
				files,
				packages: input.packages
			});
			if (!result.ok) {
				const detail = result.stderr.length > 0 ? result.stderr : result.error;
				throw new PythonError(`Python 执行失败：${detail}`, "PYTHON_FAILED");
			}
			return {
				ok: true,
				stdout: result.stdout,
				stderr: result.stderr,
				value: result.value,
				durationMs: result.durationMs
			};
		}
	});
	ctx.tools.register(tool);

	const pybot = defineTool({
		name: "pybot_reply",
		description:
			"Ask the bundled PyBot (Hugging Face pybot, Apache-2.0) for one reply. This is a local, " +
			"deterministic rule-based chatbot — NOT the cloud model and NOT a reasoning substitute. " +
			"Use it only when the user explicitly asks for pybot / the offline bot / a rule-based reply. " +
			"It has no tools, cannot read files, and its benchmark win rate is ~26% (SmolLM-360M level). " +
			"Memory is per `thread` and survives calls while the Python Worker is alive; a timeout restarts " +
			"the Worker and loses it. The first call loads ~64万 lines and can take ~25s; later calls are sub-second. " +
			"Set reset=true to forget a thread.",
		parameters: {
			text: {
				type: "string",
				required: true,
				description: "One user message for PyBot (max 20k characters)."
			},
			thread: {
				type: "string",
				description: "Conversation key (default \"default\"); separate keys keep separate memories."
			},
			reset: {
				type: "boolean",
				description: "Drop this thread's PyBot memory before the reply."
			},
			timeout_ms: {
				type: "number",
				description: `Budget for this turn (default ${PYBOT_DEFAULT_TIMEOUT_MS}, max ${MAX_TIMEOUT_MS}); the first call includes loading.`
			}
		},
		timeoutMs: MAX_TIMEOUT_MS + 5000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					reply: { type: "string", required: true },
					module: { type: "string", required: true },
					seconds: { type: "number", required: true },
					durationMs: { type: "number", required: true }
				}
			},
			render: (_args, value) => [{
				type: "text",
				text: `PyBot（${value.durationMs}ms${value.module.length > 0 ? ` · ${value.module}` : ""}）\n${value.reply}`
			}]
		},
		presentCall: (args) => ({
			card: "generic",
			title: "PyBot reply",
			kind: "execute",
			...args.text === undefined ? {} : { rawInput: args.text }
		}),
		isConcurrencySafe: () => false,
		async execute(args) {
			const input = parsePybotArgs(args);
			return runPybot(input.text, {
				thread: input.thread,
				reset: input.reset,
				timeoutMs: input.timeoutMs
			});
		}
	});
	ctx.tools.register(pybot);
}

export {
	PythonError,
	apply,
	buildPybotCode,
	clip,
	parsePybotArgs,
	parsePybotOutput,
	inject,
	name,
	parseArgs,
	readInputFiles,
	readStatus,
	runPybot,
	runPython,
	statusHint
};
